package com.jnapanam.sportszone.identity.service;
import com.jnapanam.sportszone.common.exception.UnauthorizedException;import com.jnapanam.sportszone.identity.model.*;import com.jnapanam.sportszone.notification.model.NotificationChannel;import com.jnapanam.sportszone.notification.service.NotificationService;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.Transactional;
@Service public class MfaService{@Value("${app.security.privileged-mfa-required:true}") boolean required;private final JdbcTemplate jdbc;private final PasswordEncoder encoder;private final NotificationService notifications;public MfaService(JdbcTemplate j,PasswordEncoder e,NotificationService n){jdbc=j;encoder=e;notifications=n;}
 public boolean privileged(User u){return u.getRoles().stream().anyMatch(r->r.getName()==RoleName.ADMIN||r.getName()==RoleName.SUPER_ADMIN);}
 @Transactional public void verifyOrChallenge(User u,String code){if(!required||!privileged(u))return;List<Map<String,Object>> rows=jdbc.queryForList("select enabled,challenge_hash,challenge_expires_at from privileged_mfa where user_id=?",u.getId());if(rows.isEmpty()){jdbc.update("insert into privileged_mfa(id,user_id,enabled) values(?,?,true)",UUID.randomUUID(),u.getId());challenge(u);throw new UnauthorizedException("MFA code sent. Enter the 6-digit code to continue.");}Map<String,Object> row=rows.get(0);if(!Boolean.TRUE.equals(row.get("enabled")))return;String hash=(String)row.get("challenge_hash");Object expiry=row.get("challenge_expires_at");Instant exp=expiry instanceof java.sql.Timestamp t?t.toInstant():expiry instanceof Instant i?i:null;if(code==null||code.isBlank()||hash==null||exp==null||Instant.now().isAfter(exp)){challenge(u);throw new UnauthorizedException("MFA code sent. Enter the 6-digit code to continue.");}if(!encoder.matches(code,hash))throw new UnauthorizedException("Invalid MFA code");jdbc.update("update privileged_mfa set challenge_hash=null,challenge_expires_at=null,updated_at=now() where user_id=?",u.getId());}
 private void challenge(User u){String code=String.format("%06d",java.util.concurrent.ThreadLocalRandom.current().nextInt(1000000));jdbc.update("update privileged_mfa set challenge_hash=?,challenge_expires_at=?,updated_at=now() where user_id=?",encoder.encode(code),java.sql.Timestamp.from(Instant.now().plusSeconds(600)),u.getId());notifications.notifyChannel(u.getId(),NotificationChannel.EMAIL,"SECURITY","Jnapanam sign-in verification code","Your verification code is "+code+". It expires in 10 minutes.");}}
